import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const outDir = path.join(process.cwd(), '.devns/artifacts/t3');
fs.mkdirSync(outDir, { recursive: true });
const cli = path.join(process.cwd(), 'src/cli.mjs');
const json = spawnSync(process.execPath, [cli, 'status', '--json'], { encoding: 'utf8' });
let parsed = null;
try {
  parsed = JSON.parse(json.stdout);
} catch {}
const artifact = {
  projectType: 'cli',
  json: Boolean(parsed?.ok === true && parsed?.status === 'ready'),
  stdout: json.stdout.trim(),
  attempt: process.env.DEVNS_T3_ATTEMPT
};
fs.writeFileSync(path.join(outDir, 'cli-contract.json'), JSON.stringify(artifact, null, 2) + '\n');
